// The one place the frontend talks to the Go side.
//
// The generated bindings (wailsjs/go/main/App, regenerated by `wails
// generate module` into frontend/wailsjs, see wails.json) are the contract:
// every method App exports is a named export here, so callers write
// `import { StartTerminal } from '../backend.js'` and tests mock the
// generated module. Nothing else in src/ may touch window.go.main.App.
//
// backend() and optional() exist for the few places that must tolerate a
// missing backend (dev mode, smoke tests) or a method missing from an
// older binary: they look the method up at call time instead of failing
// at import time.
export * from '../../wailsjs/go/main/App';

/** The bound App object, or undefined when no Go side is attached. */
export function backend() {
  return globalThis.window?.go?.main?.App;
}

/** The named method, or undefined when the backend lacks it. */
export function optional(name) {
  const fn = backend()?.[name];
  return typeof fn === 'function' ? fn : undefined;
}

export function hasMethod(name) {
  return optional(name) !== undefined;
}
